import subprocess, re, os
branches=["rachel","monica","phoebe","joey","chandler","ross"]
# collect all friend-message commits: sha, branch, episode
commits={}
for b in branches:
    shas=subprocess.check_output(["git","rev-list",f"origin/friend/{b}"]).decode().split()
    for sha in shas:
        body=subprocess.check_output(["git","show",sha,"--format=%B","--no-patch"]).decode()
        if "Friend-Message: 1" not in body:
            continue
        epm=re.search(r"^Episode:\s*(.+)$", body, re.M)
        ep=epm.group(1).strip() if epm else "?"
        commits.setdefault(ep, set()).add(sha)
# collect source shas in files
fileshas=set()
for root,_,files in os.walk("."):
    for f in files:
        if re.match(r"E\d+\.md", f) and root.startswith("./S"):
            path=os.path.join(root,f)
            txt=open(path).read()
            for m in re.finditer(r"Source:\s*friend/\w+\s*@\s*([0-9a-f]{40})", txt):
                fileshas.add(m.group(1))
# for each episode, missing count
for ep in sorted(commits):
    miss=[s for s in commits[ep] if s not in fileshas]
    if miss:
        print(ep, "commits", len(commits[ep]), "missing", len(miss))
PY
